do $$ declare v_ready integer; begin select count(*) into v_ready from runtime_config_definitions where definition_key in ('a2a.push.ingress.max-body-bytes','a2a.reconciliation.pipeline-ms','opendispatch.a2a-async.batch-size','opendispatch.a2a-async.enabled','opendispatch.a2a-async.poll-ms','opendispatch.a2a-async.push-handoff-batch-size','opendispatch.a2a-async.push-handoff-ms','opendispatch.a2a-authority-revocation-sweep-ms','opendispatch.a2a-read.batch-size','opendispatch.a2a-read.enabled','opendispatch.a2a-read.poll-ms','opendispatch.capability-result-retry.batch-size','opendispatch.capability-result-retry.enabled','opendispatch.capability-result-retry.poll-ms','opendispatch.mcp-read.batch-size','opendispatch.mcp-read.enabled','opendispatch.mcp-read.poll-ms','opendispatch.plan-runtime.batch-size','opendispatch.plan-runtime.poll-ms') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true; if v_ready<>19 then raise exception 'C3R2G_DOMAIN_DEFINITION_CLOSURE_INCOMPLETE expected=19 actual=%',v_ready; end if; if exists(select 1 from runtime_config_definitions where definition_key in ('handoff-context.agent-context-audit-enabled','handoff-context.default-attachment-policy','handoff-context.relay-provider','handoff-context.require-approved-snapshot-for-agent','opendispatch.operational.schedulers.a2a-remote.pool-size','opendispatch.operational.slo.remote-tracking-oldest-age-seconds') and (migration_authorized=true or admin_editable=true or review_status<>'RETIRED')) then raise exception 'C3R2G_RECLASSIFIED_AUTHORITY_LEAK'; end if; if (select count(*) from runtime_config_inventory_observations where configuration_key in ('a2a.cancellation.reconcile-delay-ms','a2a.legacy-reconcilers.cancellation-enabled','a2a.legacy-reconcilers.handoff-enabled','a2a.legacy-reconcilers.planner-only-enabled','a2a.legacy-reconcilers.result-enabled','a2a.push.ingress.max-body-bytes','a2a.reconciliation.pipeline-ms','a2a.result-reconciliation-ms','a2a.unified